1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Customer {
9	  yearsWithMHPCO: number;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	/** The MHPCO's catalogue of insurable items. Base premium and insurance value are
60	 *  independent figures; they are listed together because they describe one item type. */
61	const ITEM_CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
62	  sword: { basePremium: 100, insuranceValue: 1000 },
63	  amulet: { basePremium: 60, insuranceValue: 600 },
64	  staff: { basePremium: 80, insuranceValue: 800 },
65	  potion: { basePremium: 40, insuranceValue: 400 },
66	  rune: { basePremium: 25, insuranceValue: 250 },
67	  moonstone: { basePremium: 25, insuranceValue: 250 },
68	};
69	
70	const itemBasePremium = (item: Item): number => ITEM_CATALOGUE[item.type].basePremium;
71	
72	const BLOCK_SIZE = 3;
73	const BLOCK_BASE_PREMIUM = 60;
74	
75	const sumOfItemBasePremiums = (items: Item[]): number =>
76	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
77	
78	const itemsGroupedByType = (items: Item[]): Item[][] => {
79	  const byType = new Map<string, Item[]>();
80	  for (const item of items) {
81	    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
82	  }
83	  return [...byType.values()];
84	};
85	
86	const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;
87	
88	const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
89	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);
90	
91	const policyBasePremium = (items: Item[]): number =>
92	  itemsGroupedByType(items).reduce(
93	    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
94	    0,
95	  );
96	
97	const withFirstInsuranceSurcharge = (policyBase: number): number =>
98	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
99	
100	const roundPremiumInMHPCOsFavor = Math.ceil;
101	
102	const HIGH_ENCHANTMENT_THRESHOLD = 5;
103	
104	const isCursed = (item: Item): boolean => item.cursed === true;
105	
106	/** An item with no recorded enchantment is treated as wholly unenchanted. */
107	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
108	
109	const isHighlyEnchanted = (item: Item): boolean =>
110	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD;
111	
112	interface RiskSurcharge {
113	  appliesTo: (item: Item) => boolean;
114	  rateOfBasePremium: number;
115	}
116	
117	const RISK_SURCHARGES: RiskSurcharge[] = [
118	  { appliesTo: isCursed, rateOfBasePremium: 0.5 },
119	  { appliesTo: isHighlyEnchanted, rateOfBasePremium: 0.3 },
120	];
121	
122	const itemRiskSurcharge = (item: Item): number =>
123	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
124	    (sum, surcharge) => sum + itemBasePremium(item) * surcharge.rateOfBasePremium,
125	    0,
126	  );
127	
128	const totalRiskSurcharges = (items: Item[]): number =>
129	  items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
130	
131	/** Who the policy is for, and where it sits in their history with the MHPCO. */
132	interface QuoteContext {
133	  customer: Customer;
134	  isFollowUpContract: boolean;
135	}
136	
137	const LOYALTY_DISCOUNT = 0.2;
138	const LOYALTY_THRESHOLD_YEARS = 2;
139	
140	const isLoyal = (context: QuoteContext): boolean =>
141	  context.customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
142	
143	const loyaltyDiscount = (policyBase: number, context: QuoteContext): number =>
144	  isLoyal(context) ? policyBase * LOYALTY_DISCOUNT : 0;
145	
146	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
147	
148	const followUpContractDiscount = (policyBase: number, context: QuoteContext): number =>
149	  context.isFollowUpContract ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
150	
151	const policyWidePremium = (policyBase: number, context: QuoteContext): number =>
152	  withFirstInsuranceSurcharge(policyBase) -
153	  loyaltyDiscount(policyBase, context) -
154	  followUpContractDiscount(policyBase, context);
155	
156	const premiumBeforeFee = (items: Item[], context: QuoteContext): number =>
157	  policyWidePremium(policyBasePremium(items), context) + totalRiskSurcharges(items);
158	
159	const quotePremium = (items: Item[], context: QuoteContext): number =>
160	  roundPremiumInMHPCOsFavor(premiumBeforeFee(items, context) + PROCESSING_FEE);
161	
162	/** Payouts round down, premiums round up — both in the MHPCO's favor. */
163	const roundPayoutInMHPCOsFavor = Math.floor;
164	
165	const DEDUCTIBLE_PER_DAMAGE = 100;
166	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
167	
168	const itemInsuranceValue = (item: Item): number => ITEM_CATALOGUE[item.type].insuranceValue;
169	
170	const insuranceSum = (items: Item[]): number =>
171	  items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
172	
173	interface Policy {
174	  items: Item[];
175	  remainingCap: number;
176	}
177	
178	/** The high-enchantment clause: damage to a heavily enchanted item is reimbursed at half
179	 *  rate, on the theory that its enchantment shares the blame. Distinct from the quote-time
180	 *  high-enchantment surcharge, which has its own (lower) threshold. */
181	const HIGH_ENCHANTMENT_CLAUSE_THRESHOLD = 8;
182	const HIGH_ENCHANTMENT_CLAUSE_RATE = 0.5;
183	
184	const fallsUnderHighEnchantmentClause = (item: Item): boolean =>
185	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_CLAUSE_THRESHOLD;
186	
187	const reimbursableDamage = (damage: Damage, damagedItem: Item): number =>
188	  fallsUnderHighEnchantmentClause(damagedItem)
189	    ? damage.amount * HIGH_ENCHANTMENT_CLAUSE_RATE
190	    : damage.amount;
191	
192	const damagePayout = (damage: Damage, damagedItem: Item): number =>
193	  reimbursableDamage(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
194	
195	const findDamagedItem = (insuredItems: Item[], damage: Damage): Item => {
196	  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
197	  if (damagedItem === undefined) {
198	    throw new Error(`Item not covered by policy: ${damage.itemType}`);
199	  }
200	  return damagedItem;
201	};
202	
203	const incidentPayout = (incident: Incident, insuredItems: Item[]): number =>
204	  incident.damages.reduce(
205	    (sum, damage) => sum + damagePayout(damage, findDamagedItem(insuredItems, damage)),
206	    0,
207	  );
208	
209	/** A claim draws down the policy's remaining cap, so settling one yields a new policy state. */
210	const settleClaim = (policy: Policy, incident: Incident): [ClaimResult, Policy] => {
211	  const payout = roundPayoutInMHPCOsFavor(incidentPayout(incident, policy.items));
212	  const remainingCap = policy.remainingCap - payout;
213	  return [{ payout, remainingCap }, { ...policy, remainingCap }];
214	};
215	
216	const openPolicy = (items: Item[]): Policy => ({
217	  items,
218	  remainingCap: insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
219	});
220	
221	const findPolicy = (policies: Map<number, Policy>, policyRef: number): Policy => {
222	  const policy = policies.get(policyRef);
223	  if (policy === undefined) {
224	    throw new Error(`Unknown policy: ${policyRef}`);
225	  }
226	  return policy;
227	};
228	
229	export const runScenario = (scenario: Scenario): ScenarioResult => {
230	  const policies = new Map<number, Policy>();
231	  let quotesSoFar = 0;
232	
233	  const runStep = (step: Step, stepIndex: number): StepResult => {
234	    if (step.op === "quote") {
235	      policies.set(stepIndex, openPolicy(step.items));
236	      const context = {
237	        customer: scenario.customer,
238	        isFollowUpContract: quotesSoFar > 0,
239	      };
240	      quotesSoFar += 1;
241	      return { premium: quotePremium(step.items, context) };
242	    }
243	
244	    const [result, settledPolicy] = settleClaim(
245	      findPolicy(policies, step.policy),
246	      step.incident,
247	    );
248	    policies.set(step.policy, settledPolicy);
249	    return result;
250	  };
251	
252	  return { results: scenario.steps.map(runStep) };
253	};
